diff --git a/src/main/java/com/sprintdesk/issue/IssueStatusService.java b/src/main/java/com/sprintdesk/issue/IssueStatusService.java
--- a/src/main/java/com/sprintdesk/issue/IssueStatusService.java
+++ b/src/main/java/com/sprintdesk/issue/IssueStatusService.java
@@ -1,6 +1,14 @@
 package com.sprintdesk.issue;

 @Service
 @RequiredArgsConstructor
 public class IssueStatusService {
+    private final IssueRepository issues;
+
+    @Transactional
+    public Issue changeStatus(Long issueId, Long memberId, IssueStatus nextStatus) {
+        Issue issue = issues.findById(issueId).orElseThrow();
+        issue.changeStatus(nextStatus);
+        return issues.save(issue);
+    }
 }
